class Solution:
    def longestBeautifulSubstring(self, word: str) -> int:
        n = len(word)
        best = 0
        for i in range(n):
            seen = set()
            j = i
            while j < n and (j == i or word[j] >= word[j - 1]):
                seen.add(word[j])
                j += 1
            if len(seen) == 5:
                best = max(best, j - i)
        return best

