import java.util.*;

class Solution {
    public int longestBeautifulSubstring(String word) {
        int n = word.length(), best = 0;
        for (int i = 0; i < n; i++) {
            Set<Character> seen = new HashSet<>();
            int j = i;
            while (j < n && (j == i || word.charAt(j) >= word.charAt(j - 1))) {
                seen.add(word.charAt(j));
                j++;
            }
            if (seen.size() == 5) best = Math.max(best, j - i);
        }
        return best;
    }
}

