class Solution {
    public int longestBeautifulSubstring(String word) {
        int best = 0, length = 1, distinct = 1;
        for (int i = 1; i < word.length(); i++) {
            char cur = word.charAt(i), prev = word.charAt(i - 1);
            if (cur >= prev) {
                length++;
                if (cur > prev) distinct++;
            } else {
                length = 1;
                distinct = 1;
            }
            if (distinct == 5) best = Math.max(best, length);
        }
        return best;
    }
}

